function PTTM_ExtRegister()
	if PTTM_EXT_REGISTERED then return end
	local i = 1
	while PTTM_EXT_SCRIPTS[i] do
		ReLoadScript(PTTM_EXT_SCRIPTS[i])
		i = i + 1
	end
	i = 1
	while PTTM_EXT_PAK[i] do
		call(ReLoadScript, { PTTM_EXT_PAK[i] }, "x", PTTM_ExtNop)
		i = i + 1
	end
	PTTM_EXT_REGISTERED = 1
end

function PTTM_ExtNop(m)
end

-- one scan over the NPC table: region placeholders with the same template on the same cell
function PTTM_ExtAdopt()
	local i = 1
	local want = 0
	local k = 1
	while PTTM_EXT_NPCS[k] do
		if PTTM_EXT_NPCS[k][7] == 1 then want = want + 1 end
		k = k + 1
	end
	if want == 0 then return 0 end
	local got = 0
	while i < PTTM_EXT_MAX_NPC and got < want do
		local nm = GetNpcName(i)
		if nm and nm ~= "" then
			local w, x, y = GetNpcPos(i)
			if w == 1073 then
				local tpl = GetNpcTemplateID(i)
				k = 1
				while PTTM_EXT_NPCS[k] do
					local s = PTTM_EXT_NPCS[k]
					if s[7] == 1 and not PTTM_EXT_NPC_IDX[k] and tpl == s[2] and abs(x - s[3]) <= 1 and abs(y - s[4]) <= 1 then
						SetNpcName(i, s[5])
						SetNpcScript(i, s[6])
						PTTM_EXT_NPC_IDX[k] = i
						got = got + 1
					end
					k = k + 1
				end
			end
		end
		i = i + 1
	end
	return got
end

function PTTM_ExtSpawn(tpl, lv, m, x, y, removable)
	local sw = SubWorldID2Idx(m)
	if sw == nil or sw < 0 then return 0 end
	local ni = AddNpc(tpl, lv, sw, x * 32, y * 32, removable)
	if ni == nil or ni <= 0 then ni = AddNpc(tpl, lv, sw, (x + 2) * 32, y * 32, removable) end
	if ni == nil or ni <= 0 then ni = AddNpc(tpl, lv, sw, x * 32, (y + 2) * 32, removable) end
	if ni == nil or ni <= 0 then return 0 end
	return ni
end

function PTTM_ExtEnsureNpcs()
	local k = 1
	while PTTM_EXT_NPCS[k] do
		local s = PTTM_EXT_NPCS[k]
		local ni = PTTM_EXT_NPC_IDX[k]
		if not (ni and ni > 0 and GetNpcName(ni) == s[5]) then
			ni = PTTM_ExtSpawn(s[2], 1, s[1], s[3], s[4], 0)
			if ni > 0 then
				SetNpcName(ni, s[5])
				SetNpcScript(ni, s[6])
				PTTM_EXT_NPC_IDX[k] = ni
			end
		end
		k = k + 1
	end
end

function PTTM_ExtEnsureMobs()
	local k = 1
	while PTTM_EXT_MOBS[k] do
		local s = PTTM_EXT_MOBS[k]
		local ni = PTTM_EXT_MOB_IDX[k]
		if not (ni and ni > 0 and GetNpcName(ni) == s[6] and GetNpcParam(ni, 1) == PTTM_EXT_K_PACK) then
			ni = PTTM_ExtSpawn(s[2], s[3], s[1], s[4], s[5], 1)
			if ni > 0 then
				SetNpcName(ni, s[6])
				SetNpcScript(ni, "\\script\\phongthan\\tienma\\mob_kill.lua")
				SetNpcParam(ni, 1, PTTM_EXT_K_PACK)
				PTTM_EXT_MOB_IDX[k] = ni
			end
		end
		k = k + 1
	end
end

function PTEXT_tienma_Tick()
	PTTM_ExtRegister()
	if not PTTM_EXT_ADOPTED then
		PTTM_EXT_ADOPTED = 1
		PTTM_ExtAdopt()
	end
	PTTM_ExtEnsureNpcs()
	PTTM_ExtEnsureMobs()
end
